from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
DOCS = ROOT / "docs"


def para(text):
    return text.strip() + "\n"


def heading(text):
    return "\n" + text.strip().upper() + "\n\n"


def subheading(text):
    return "\n" + text.strip() + "\n\n"


def numbered(items):
    return "\n".join(f"{i}. {item}" for i, item in enumerate(items, 1)) + "\n"


def table(title, headers, rows):
    lines = [title, " | ".join(headers), " | ".join(["-" * len(h) for h in headers])]
    lines.extend(" | ".join(str(cell) for cell in row) for row in rows)
    descriptions = {
        "Таблица 1": "В таблице 1 представлены основные процессы фитнес-клуба, которые определяют границы автоматизации. Из таблицы видно, что система должна обслуживать не один изолированный сценарий, а полный цикл взаимодействия клиента, администратора и тренера.",
        "Таблица 2": "Таблица 2 показывает, какие проблемы возникают при ручном учете и каким образом они устраняются средствами информационной системы. Эти сведения используются при формировании требований к проекту.",
        "Таблица 3": "В таблице 3 сопоставлены готовые платформы и собственная разработка. Сравнение подтверждает целесообразность реализации индивидуального веб-приложения для учебного и прикладного проекта.",
        "Таблица 4": "Таблица 4 раскрывает назначение основных технологий проекта. Выбранный стек обеспечивает серверную логику, хранение данных, авторизацию, проверку форм, уведомления, отчетность и тестирование.",
        "Таблица 5": "В таблице 5 показано распределение модулей по каталогам проекта. Такое разделение соответствует модульному подходу и упрощает сопровождение приложения.",
        "Таблица 6": "Таблица 6 описывает blueprint-разделы Flask-приложения. Она показывает, какие функциональные области выделены в отдельные группы маршрутов.",
        "Таблица 7": "В таблице 7 перечислены сущности базы данных и их назначение. Таблица дополняет ER-диаграмму и помогает связать логическую модель с реализацией в коде.",
        "Таблица 8": "Таблица 8 показывает пользовательские сценарии, которые реализованы в приложении. Эти сценарии отражают основные действия клиента фитнес-клуба.",
        "Таблица 9": "В таблице 9 приведены административные разделы системы. Она показывает, какие данные может изменять сотрудник клуба и какую практическую задачу решает каждый раздел.",
        "Таблица 10": "Таблица 10 раскрывает расчетные свойства пользовательского абонемента. Эти свойства используются для определения активности, срока действия, остатка посещений и возможности заморозки.",
        "Таблица 11": "Таблица 11 фиксирует набор автоматизированных проверок. Она показывает, что тестирование охватывает публичные страницы, авторизацию, пользовательские функции, административный доступ и модели.",
        "Таблица 12": "В таблице 12 отражен практический результат разработки. Сопоставление состояния до и после внедрения показывает организационный эффект автоматизации.",
        "Таблица 13": "Таблица 13 описывает основные механизмы защиты. Они обеспечивают хранение паролей в безопасном виде, контроль сессий, разграничение ролей и проверку данных.",
        "Таблица 14": "Таблица 14 содержит детализированные тест-кейсы. Ее можно использовать как основу для ручной проверки приложения при демонстрации и приемке.",
        "Таблица 15": "Таблица 15 показывает организационный эффект внедрения системы. Она связывает программные функции с практическими изменениями в работе фитнес-клуба.",
        "Таблица 16": "В таблице 16 приведены проектные риски и способы их снижения. Анализ рисков подтверждает, что при разработке учитывались эксплуатационные и организационные ограничения.",
    }
    description = next((text for key, text in descriptions.items() if title == key or title.startswith(key + " -")), "")
    if description:
        lines.append("")
        lines.append(description)
    return "\n".join(lines) + "\n"


def figure(path, caption, description):
    return f"[[IMAGE:{path}|{caption}]]\n{description}\n"


